// Renders every generated file from eng.config.yml. Pure: config in, {path: content} out.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { resolvePolicy } from './e2e-policy.mjs';
const PKG = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const HDR = (c = '#') => `${c} GENERATED by eng from eng.config.yml. Do not edit; edit the config and run \`eng sync\`.`;

export const BEGIN = '<!-- eng:begin -->', END = '<!-- eng:end -->';

function list(xs) { return (xs || []).map(x => `- ${x}`).join('\n'); }
function choice(c) { return `**${c.use}** — ${c.why} _(${c.decision || 'DRAFT'})_`; }

// Check ids from the repo's checks_dir (each is an executable behaviour check run by `eng verify maintain`).
export function checkIds(cfg) {
  const d = path.join(process.cwd(), cfg.verification?.checks_dir ?? '.eng/checks');
  return fs.existsSync(d) ? fs.readdirSync(d).filter(f => f.endsWith('.sh')).map(f => f.slice(0, -3)).sort() : [];
}
// One line per stage. Rendered into AGENTS.md and printed by `eng init`.
export const ROUTER = [
  ['plan', '`poteto-mode` (it picks the playbook: bug-fix, feature, refactoring ...), then `how` / `why` / `architect`; `figure-it-out` for large work; `grilling` / `grill-with-docs` for product calls; `find-the-laws` for rules that must always hold'],
  ['build', 'the playbook steps; `tdd` for bug fixes; `typescript-best-practices` on every .ts/.tsx edit; `show-me-your-work` for long or unattended runs'],
  ['verify', '`principle-prove-it-works`, the repo `verify-<app>` skill (use it wherever pstack says `control-cli` / `control-ui`), `eng verify create <id>`; `interrogate` for contested design, `blast-radius` for small risky diffs'],
  ['ship', 'author: the Opening a PR playbook (`no-comments`, then `technical-writing` + `unslop`) up to merge-ready, never merge; shipping manager: the serial loop in SHIPPING.md (`eng ship next`)'],
  ['retro', '`eng-retro` (`eng retro`) after each merged PR, then `correct` for any class it finds'],
];
export const ROUTE_RULE = 'To use a skill, read `.agents/skills/<name>/SKILL.md` and follow it. Do not rely on description matching or the Skill tool: most of these skills are manual-only and will not load on their own.';
export const STEER = 'Leads that spawn or steer coding threads (e.g. T3) start the message with one line naming the mode and the playbook, then the job, e.g. "/poteto-mode -> Shipping playbook: verify commit <sha> with verify-<app>, record eng verdict". This is the primary path; the router above is the fallback.';
export const SPAWN_RULE = 'one line naming the mode and playbook, e.g. "/poteto-mode -> Shipping playbook: verify commit <sha> with verify-<app>, record eng verdict".';
// Which poteto-mode playbook (vendor/pstack/skills/poteto-mode/playbooks/<file>) goes with which job.
export const PLAYBOOKS = [
  ['Drive the author\'s own PR to merge-ready (conflicts, review threads, CI). NOT an independent review', 'Babysit', 'playbooks/babysit.md', '/poteto-mode -> Babysit playbook (drive): get PR #<n> to merge-ready; you are the author side, not the verifier'],
  ['Independent verdict on a commit by an agent that did not write it, then land', 'Shipping', 'playbooks/shipping.md', '/poteto-mode -> Shipping playbook: verify commit <sha> with verify-<app>, record eng verdict'],
  ['Full autonomous program: one owner per PR from build to merge, root swarm-verifies each round', 'Autopilot-full', 'playbooks/autopilot-full.md', '/poteto-mode -> Autopilot-full playbook: run queue <list> to merge'],
  ['Full autonomy up to a verified linear stack the operator lands', 'Autopilot-stack', 'playbooks/autopilot-stack.md', '/poteto-mode -> Autopilot-stack playbook: build and verify <list> as one stack; do not merge'],
  ['Bug fix / feature / refactor', 'Bug fix, Feature, Refactoring', 'playbooks/bug-fix.md, feature.md, refactoring.md', '/poteto-mode -> Bug fix playbook: <issue>'],
];
export const SPAWN_RULES = [
  'Babysit is not review. A babysitter drives the author\'s PR to merge-ready; the verdict comes from a separate Shipping (verification) spawn by an agent that did not write the code.',
  'When the change adds a surface (route, screen, command, API, job) the repo\'s `verify-<app>` skill does not cover, the spawn message must also require `maintain-verification-skill` for that surface before the verdict.',
  'Write spawn and steer messages in plain prose with normal spacing between words. Re-read the message before sending; a message with its spaces stripped out is not sent.',
];
export function spawnText() {
  return `${STEER}

| Job | Playbook | File (poteto-mode) | Spawn line |
|---|---|---|---|
${PLAYBOOKS.map(([j, p, f, l]) => `| ${j} | ${p} | \`${f}\` | \`${l}\` |`).join('\n')}

${SPAWN_RULES.map(r => `- ${r}`).join('\n')}`;
}
// Server ruleset advice: non-strict required checks. eng never edits rulesets.
export function rulesetAdvice(cfg) {
  const b = cfg.project.default_branch;
  return `- Ruleset on \`${b}\`: require the gate status checks (\`${(cfg.gates?.required || []).join('`, `') || 'eng gate'}\` via \`eng ci-verdict\`) and squash merge; block force-push and deletion.
- Required checks are NOT strict: leave "Require branches to be up to date before merging" (\`strict_required_status_checks_policy\` / \`strict\`) OFF. Strict up-to-date is not recommended: it forces an update-branch and a full re-run on every PR after every merge, serialising the queue for little safety.
- Safety comes from the full run on \`${b}\` after every merge plus an immediate revert on red (no fix-forward). The verdict carries over by patch-id: an update-branch that leaves the patch unchanged keeps it (\`eng verdict check\`).`;
}
export const CI_HYGIENE = [
  'No duplicate dispatches. Push once and let the push or pull_request trigger start CI. Do not also fire `workflow_dispatch`, `gh workflow run`, a Buildkite "New build" or a rebuild for the same SHA.',
  'Use `workflow_dispatch` (or a manual build) only deliberately: a run the triggers do not cover, or one re-run of a failed job you are investigating. Say why in the PR.',
  'Group runs with concurrency: one group per workflow and ref, e.g. `concurrency: { group: ${{ github.workflow }}-${{ github.ref }}, cancel-in-progress: ${{ github.event_name == \'pull_request\' }} }`. Cancel superseded PR runs; never cancel runs on the default branch (the post-merge full run is the backstop). Buildkite: "Cancel intermediate builds" on PR branches only.',
];
// Linked from every rendered AGENTS.md (starter pack) and renovation SHIPPING.md. Consuming repos do not ship principles/, so it is a URL.
export const PRINCIPLES_LINE = 'Principle: [Slow down to speed up: trust is earned through systems built on formal verification](https://github.com/Slaytek-Systems/eng-standard/blob/main/principles/slow-down-to-speed-up.md). Read it before changing checks, gates or autonomy.';
export function routerText() { return ROUTER.map(([k, v]) => `- **${k}:** ${v}`).join('\n'); }

export function agentsBlock(cfg) {
  const c = cfg.project.commands, m = cfg.merge, v = cfg.verification;
  return `${BEGIN}
<!-- ${HDR('').trim()} -->
## Slaytek Systems engineering standard (${cfg.project.name})

Read \`SHIPPING.md\` before shipping and \`STACK.md\` before adding a language, framework or tool.

${PRINCIPLES_LINE}

### Commands
| Gate | Command |
|---|---|
${Object.entries(c).map(([k, x]) => `| ${k} | \`${x}\` |`).join('\n')}
| everything | \`eng gate\` (skipped or missing = failed) |
${cfg.e2e ? `| e2e needed? | \`eng e2e-required\`: ${e2ePolicyLine(cfg)} |\n` : ''}
### Skill router
${ROUTE_RULE}
${routerText()}

### Starting or steering a thread
${spawnText()}

### CI hygiene
${CI_HYGIENE.map(r => `- ${r}`).join('\n')}

### How work runs (pstack leads)
- Start any non-trivial task with the \`poteto-mode\` skill. It picks a playbook (bug fix, feature, refactoring ...), copies its steps into your todo list and calls the other pstack skills as steps need them. \`poteto-help\` answers "which skill?".
- Answer facts by running something (\`how\`, a prototype), not by asking. Ask the human only product or preference calls; use \`grilling\` / \`grill-with-docs\` for those, and \`domain-modeling\` for the glossary and ADRs.
- This repo needs one \`verify-<app>\` skill: generate it with \`create-verification-skill\`, keep it honest daily with \`maintain-verification-skill\`. \`e2e-flow\` is the Drive harness it calls.
${cfg.audits?.maintain_verification ? `- Daily audit (${cfg.audits.maintain_verification.schedule}): run \`maintain-verification-skill\` on \`${cfg.audits.maintain_verification.target}\` exactly as written. Outcome clean / changed (one PR, edits only that skill's dir) / blocked. Product bugs it finds are reported, never patched in docs. Schedule: \`.eng/ci/audit.yml\`.\n` : ''}- Learning loop: \`eng retro\` (skill \`eng-retro\`) after a PR or daily. It reads \`.eng/mistakes.jsonl\` (gate failures and FAIL verdicts are logged there automatically), proposes one fix per repeated class in \`correct\` order, and changes nothing until Matt approves.
- Model roles: \`setup-pstack\` writes \`.eng/pstack-models.md\`; a role with no line keeps the skill default.
- Host mapping (pstack is written for Cursor): \`Task\` = your agent's subagent tool; \`subagent_type: "poteto-agent"\` / \`"Comment Sicko"\` = the definitions in \`${path.dirname(cfg.agents.skills_dir)}/agents/\`; \`AskQuestion\` = ask the user; \`environment: "cloud"\` = a cloud or background agent if you have one, else a local worktree; model slugs = your host's equivalents; \`~/.cursor/projects/<slug>/agent-transcripts\` = your host's transcript store (Claude Code \`~/.claude/projects/<slug>/\`, Codex \`~/.codex/sessions/\`). \`setup-benny\`, \`triage-issue-reports\`, \`reproduce-and-fix-issues\` and \`make-bot-ui\` need Cursor Automations / Grok Bot routines and are installed but dormant.

### eng adds (each defers to the pstack skill named)
| eng | does | defers to |
|---|---|---|
| \`eng-verify\` (\`eng verify create/maintain\`) | records fail-before/pass-after verdicts as git notes; re-checks them by patch-id after main merges in | \`tdd\` + Bug fix step 5 (failing first), Shipping step 3 (patch-id), \`principle-prove-it-works\` |
| \`find-the-laws\` → \`write-law-and-proof\` → \`law-conformance\` | rules that hold for all inputs, proved in Bend, tied to shipped code | \`principle-model-the-domain\`, \`principle-type-system-discipline\` |
| \`property-test\` | fast-check over all inputs | \`principle-test-behavior-not-implementation\` (keep literal-value tests too) |
| \`add-gate\` | one write path + lint | \`correct\` level 1-2, \`principle-boundary-discipline\` |
| \`custom-lint\` | lint rule + fixture, target of \`eng mistake\` at ${v.repeat_threshold} | \`correct\` (try architecture and types first) |
| \`e2e-flow\` | TesterArmy e2e flow + evidence per SHA | \`create-verification-skill\` (it is the Drive section) |

${cfg.laws?.enabled ? `
### Laws (Bend)
- run \`bend guide\` to learn it
- use \`${cfg.laws.laws_file}\` to keep important rules (human-owned; agents draft, Matt approves)
- run \`bend ${cfg.laws.proof_file}\` before committing (\`eng laws\`)
` : ''}
### Rule → enforcer
| Rule | Enforced by |
|---|---|
| Rebase only on feature branches; never on ${[...new Set([cfg.project.default_branch, ...(cfg.project.protected_branches ?? [])])].join(', ')} | \`.githooks/pre-rebase\` (local) |
| No force-push or delete on protected branches | \`.githooks/pre-push\` + agent deny list (local); server ruleset is the real wall (not applied by v0) |
| Merge needs a verdict from an agent that did not write the code, bound to patch-id | \`eng verdict check\` (gate \`verdict\`) |
| No \`--no-verify\`, no admin merge (\`--admin\`) | agent deny lists only; hooks cannot see these. CI required checks are the wall |
| Off-stack language/framework | \`eng stack-check\` |
| Generated files match config | \`eng drift-check\` |
| Tests, e2e and fallow write only under the per-run \`$ENG_TMP\` (removed on exit, failure or signal) | \`eng gate\` / \`eng e2e\` set ENG_TMP + TMPDIR; \`eng lint\` rule \`test-bare-tmpdir\`${cfg.hygiene?.tmp_lint === false ? ' (OFF: hygiene.tmp_lint false)' : ''}; vitest globalSetup \`.eng/test-tmp.mjs\` |
| Remove your worktree when your thread settles or its PR merges; never delete unpushed or dirty ones | \`eng clean --worktrees --apply\` (removes only merged/upstream-deleted, fully pushed, clean worktrees; reports the rest) |
${(cfg.constraints?.rules || []).map(r => `| ${r.id} | \`eng lint\` (proven on ${r.proven_by.incident}) |`).join('\n')}
${checkIds(cfg).map(id => `| ${id} | \`eng verify maintain\` check \`${cfg.verification.checks_dir}/${id}.sh\` |`).join('\n')}
${(cfg.agents?.rules || []).map(r => `| ${r.rule} | ${r.enforced_by ? (r.enforced_by === 'review' ? `reviewer judgment (${r.why || 'NO REASON: eng verify maintain fails'})` : `\`${r.enforced_by}\``) : '**NOTHING** (eng verify maintain fails)'} |`).join('\n')}
${cfg.isolation ? `| Devbox project isolation: unique names, ports and state in \`.eng/project.toml\`; reach services only through \`eng connect\`; only the starter stops a service (\`eng stop\`); no secrets on argv | \`eng isolation check\` (${cfg.isolation.mode === 'fail' ? 'fails' : 'warn only'}); \`eng run-service\` ownership records |\n` : ''}${cfg.db?.additive_only ? '| DB changes additive only | `eng lint` rule `db-additive-only` |\n' : ''}${cfg.flags?.file ? `| New flags default off | \`eng lint\` rule \`flags-default-off\` |\n` : ''}
### Branches and merge
- Feature branches: rebase into small ordered commits and onto \`origin/${cfg.project.default_branch}\` as pstack's Opening a PR says; push with \`git push --force-with-lease\`. A rebase that keeps the patch keeps its verdict (patch-id). Never rebase or force-push a protected branch.
- Merge owner for this repo: **${m.owner}**. Command: \`${m.command}\`. There is no global merge rule.
- Disk hygiene: when your thread settles or its PR merges, confirm your commits are pushed (\`git status -sb\`, \`git log @{u}..\`), then run \`eng clean --worktrees --apply\` from the main checkout. It never deletes unpushed or dirty worktrees; report those to the repo lead. \`eng clean --apply\` removes stale \`$ENG_TMP\` dirs. Scratch only under \`$ENG_SCRATCH\`/\`$ENG_TMP\` (\`eng launch -- <cmd>\` or \`eng verdict round -- <cmd>\`, removed on exit), never bare /tmp; one shared cache per toolchain (\`hygiene.caches\`); containers \`--rm\` or labelled (\`eng clean --containers\`); evidence per PR (\`eng clean --evidence\`); \`eng doctor\` checks the config. Clean up on merge or close: one worktree per PR reused across review rounds, evidence is logs/diffs/verdicts/screenshots only, no installs in review-only worktrees, shared package stores and build caches, media off the box. See \`SHIPPING.md\` §5.
${cfg.ship ? `- Shipping: author agents stop at merge-ready and never merge. A fresh-context verifier gives the verdict on the head SHA. Only the shipping manager (${cfg.ship.manager}) merges, reverts and reorders, one PR at a time (\`eng ship next\`). \`${cfg.ship.high_risk?.label || 'risk:high'}\` PRs need Matt's approval first. See \`SHIPPING.md\` Shipping model.\n` : ''}
### Fixed rules (also in SHIPPING.md §0; do not edit per repo)
16. **A red-\`${cfg.project.default_branch}\` recovery must end in either \`${cfg.project.default_branch}\` green or an explicit escalation.** Escalate to the repo lead (and Matt if the change is Matt-gated), stating the cause, the owner and the next step. A recovery thread may never just finish while \`${cfg.project.default_branch}\` is still red (Motus f193b345, 14 Oct 2026: two recovery threads ended with main still red).
17. **Before reporting merge or ship status, read live state from GitHub.** PR merged?, merge SHA, \`${cfg.project.default_branch}\`'s latest checks. Never report from memory or a failed command's output (\`eng ship next\` prints the live merged state and main checks). (Core Edge #257, 14 Oct 2026: a thread reported "no merge SHA yet" when the PR had merged at 5:28 AM AEDT as ec67f831.)
18. **Clean up on merge or close.** When a PR merges or closes, its worktrees and evidence are deleted. Reuse one worktree per PR, keep evidence to logs, diffs, verdicts and screenshots, share package stores and build caches, keep media off the box, and make temp dirs delete themselves (SHIPPING.md §5). (Devbox forensics, 17 Oct 2026: about 100 GB of agent leftovers.)
19. **Briefs live in Core.** Any brief one agent hands another (a builder, reviewer or verifier thread) is written to Core first, as a note in the repo's Core space tagged \`brief\`. The worker thread's prompt names the Core note id; it may paste the brief inline too. \`/tmp\` or any other scratch path is never the only copy; a local file is only a convenience copy of the Core note. A revision updates the same note (Core keeps the history); never create a second note such as r2. (Approved by Matt, 19 Oct 2026: verdicts and audits must see exactly what a builder was told, even after the devbox restarts or \`/tmp\` is cleaned.)
20. **Callback contract.** Scripts, CI jobs and T3 threads that wake a bot post only when work is done, blocked or needs a decision. No progress pings, no all-clears. The post is one line: \`<status> <thread-id> <one short clause>\`, where status is \`done\`, \`blocked\` or \`needs-decision\`. Detail goes in a Core note or file, named by its id. A woken bot reads only that payload and at most the last 2 messages of the named thread, never the whole history. If nothing needs a decision or reply, it exits without a message. (Approved by Matt, 19 Oct 2026.)
21. **Hand off by default.** Any coding or bulk job over about 20 steps goes to a T3 thread: a builder, plus an independent verifier as this standard already requires. The lead hands it off and ends its own run, then wakes on the rule-20 \`done\` or \`blocked\` callback. Leads check progress with cheap live-state checks (the verdict status, CI, \`gh pr checks\`, \`gh pr view\`), not by reading whole threads or diffs. Decisions for Matt and client-facing communication stay with the lead. (Approved by Matt, 19 Oct 2026. Tested first on Eng Manager's Fleet Control Tower webhook from 19 Oct; project leads switch on Wed 21 Oct 2026.)
${END}`;
}

export function stackMd(cfg) {
  const s = cfg.stack;
  return `<!-- ${HDR('').trim()} -->
# STACK.md: ${cfg.project.name}

Status: **${s.status}**. Every choice below is a draft decision for Matt until marked APPROVED in eng.config.yml.
\`eng stack-check\` fails on a language, framework or lockfile not listed here, unless \`stack.exceptions\` records it with a reason.

## Defaults
| Area | Choice |
|---|---|
${Object.entries(s.defaults).map(([k, c]) => `| ${k} | ${choice(c)} |`).join('\n')}

## Allowed languages
${list(s.languages.allowed)}

## When another language is justified
${Object.entries(s.languages.justified_when || {}).map(([k, w]) => `- **${k}**: ${w}`).join('\n')}

## Allowed frameworks / libraries (checked)
${list(s.frameworks.allowed)}

## Recorded exceptions
${(s.exceptions || []).length ? s.exceptions.map(e => `- ${e.kind} \`${e.name}\`: ${e.reason} (approved by ${e.approved_by || 'PENDING'})`).join('\n') : '- none'}

## Notes
${list(s.notes)}
`;
}

// Shipping model (ship:). Empty when the repo has no ship: section, so older configs render unchanged.
export function shipMd(cfg) {
  const s = cfg.ship; if (!s) return '';
  const h = s.high_risk || {}, L = h.label || 'risk:high', q = s.merge_queue;
  return `
### Shipping model
**Roles**
- **Author:** stops at merge-ready (gate green, PR description, evidence, risk label). Never merges.
- **Verifier:** a fresh-context agent that did not write the code records the verdict (\`eng verdict\`), bound to the head SHA / patch-id.
- **Shipping manager:** ${s.manager}. The only one that merges, reverts and reorders. Never writes code.${(s.manager_also || []).length ? ` Also owns ${s.manager_also.join(' and ')}.` : ''}
- **Matt:** only approves \`${L}\` PRs (${(h.reasons || []).join(', ')}).${(h.paths || []).length ? ` High risk by default: ${h.paths.map(x => `\`${x}\``).join(', ')}.` : ''} Matt never presses merge.

**Loop** (shipping manager, one PR at a time, run whenever a PR becomes ready; \`eng ship next\` prints the next PR and these commands)
1. Pick the oldest ready PR with a PASS verdict. Skip \`${L}\` PRs Matt has not approved yet.
2. \`gh pr update-branch <n>\`.
3. Wait for the gate on the new head. If only main changed (same patch-id) the verdict stands (\`eng verdict check\`); otherwise send it back to the verifier.
4. \`gh pr merge <n> --squash --delete-branch --match-head-commit <sha>\`.
5. Confirm main is green after the merge, including the full post-merge e2e run. If anything is red (a red e2e on main above all: PR e2e is path-based, so main is the backstop), revert immediately (\`gh pr revert <n>\` or \`git revert\` in a PR), get main green again, then return the PR to its author. Do not fix forward on main. (motus #285, 13 Oct 2026: red post-merge e2e on main, reverted at once.)
6. Log it in the repo's Core status note.

**Escalation**
- Two gate failures: back to the author with the reason.
- \`${L}\`: send it to Matt as soon as it is ready, one at a time, with a one-line summary, the evidence and the PR link. Once he approves, the shipping manager merges it.
- Red-main recovery ends only when main is green, or with an explicit escalation to the repo lead (and Matt if Matt-gated) naming cause, owner and next step. Never finish while main is still red.
- Before reporting merge or ship status, read live GitHub state (PR merged?, merge SHA, main checks). \`eng ship next\` prints them; never report from memory or a failed command.
${q ? `- **Merge queue (opted in):** ${q.provider || 'github'}, max group ${q.max_group_size ?? 'small'}; CI must run on \`${q.ci_trigger || 'merge_group'}\`.\n` : ''}
TODO: fold releases and tagging into this loop (not designed yet).
`;
}

export function shippingMd(cfg) {
  const t = fs.readFileSync(path.join(PKG, 'templates/SHIPPING.md'), 'utf8');
  const c = cfg.project.commands;
  return t.replaceAll('<REPO>', cfg.project.name)
    .replaceAll('<BASE>', cfg.project.default_branch)
    .replaceAll('<MERGE_OWNER>', cfg.merge.owner)
    .replaceAll('<MERGE_COMMAND>', cfg.merge.command)
    .replaceAll('<MERGE_METHOD>', cfg.merge.method)
    .replace('<SHIP>', shipMd(cfg))
    .replace('<SPAWN>', spawnText())
    .replace('<RULESET>', rulesetAdvice(cfg))
    .replace('<CI_HYGIENE>', CI_HYGIENE.map(r => `- ${r}`).join('\n'))
    .replaceAll('<FLAKE_RUNS>', String(cfg.e2e?.flake_runs ?? 3))
    .replaceAll('<GATE>', 'eng gate')
    .replaceAll('<TEST>', c.test)
    .replaceAll('<FLAGS>', cfg.flags?.file || 'none')
    .replaceAll('<MIGRATIONS>', cfg.db?.migrations || 'none')
    .replace('<!--HDR-->', `<!-- ${HDR('').trim()} -->`);
}

export function pipeline(cfg) {
  const g = cfg.gates.required;
  const steps = g.map(id => `  - label: "eng ${id}"\n    key: "${id}"\n    command: "npx eng ${id === 'verify' ? 'verify maintain' : id === 'rules' ? 'rules prove' : id === 'launch' ? 'launch-check' : id === 'lint' ? `lint --config-from origin/${cfg.project.default_branch}` : id === 'e2e' ? 'e2e --if-required' : id}"\n    soft_fail: false${id === 'e2e' ? `\n    artifact_paths: "${cfg.e2e.evidence_dir}/**/*"` : ''}`).join('\n');
  return `${HDR()}
# Only main's copy of this file is ever uploaded (stored bootstrap step). soft_fail is never true.
# e2e: ${e2ePolicyLine(cfg)}
steps:
${steps}
  - wait: ~
  - label: "eng required-checks (skipped = failed)"
    command: "npx eng ci-verdict ${g.join(' ')}"
`;
}

export function e2ePolicyLine(cfg) {
  const p = resolvePolicy(cfg.e2e);
  if (p.mode === 'always') return 'runs on every PR and on main (e2e.policy.mode: always).';
  return `PRs run it only when they touch ${Object.keys(p.run_on).join(', ')} paths or carry ${p.labels.join(', ')}; docs-only, config-only (non-CI) and test-only PRs pass as NOT REQUIRED (\`eng e2e-required\` explains why). main runs the full suite after every merge${p.main.nightly.enabled ? ' and nightly' : ''}; red on main = revert now.`;
}
// Nightly full e2e (backstop). Rendered only when e2e.policy.main.nightly.enabled. eng never creates schedules.
export function e2eNightlyPipeline(cfg) {
  const n = resolvePolicy(cfg.e2e).main.nightly;
  return `${HDR()}
# Nightly full e2e on ${cfg.project.default_branch} (backstop). Create the schedule in Buildkite (Pipeline Settings > Schedules,
# cron "${n.cron}", branch ${cfg.project.default_branch}) pointing at this file. A red run = shipping manager reverts the culprit.
steps:
  - label: "eng e2e (nightly, full)"
    key: "e2e-nightly"
    command: "npx eng e2e --if-required"
    env:
      ENG_E2E_EVENT: nightly
    soft_fail: false
    artifact_paths: "${cfg.e2e.evidence_dir}/**/*"
`;
}

// Daily maintain-verification audit as a scheduled pipeline (Buildkite pipeline schedule points at this file).
// Defined here; no schedule is created by eng. The step hands the vendored skill to a headless agent.
export function auditPipeline(cfg) {
  const a = cfg.audits.maintain_verification;
  return `${HDR()}
# Daily audit: pstack maintain-verification-skill, unchanged. Create the schedule in Buildkite (Pipeline Settings > Schedules,
# cron "${a.cron}") pointing at this file. eng never creates schedules. Outcome: clean (no PR) / changed (one PR) / blocked.
steps:
  - label: "audit: maintain-verification-skill (${a.target})"
    key: "audit-maintain-verification"
    command: |
      ${a.agent_command.replaceAll('{skill}', `${cfg.agents.skills_dir}/maintain-verification-skill/SKILL.md`).replaceAll('{target}', a.target)}
    soft_fail: false
    artifact_paths: "${cfg.e2e?.evidence_dir ?? '.eng/evidence'}/**/*"
`;
}
const ENG_CHECKS = '\$ENG drift-check && \$ENG stack-check && \$ENG lint';
const shQuote = (cmd) => `'${cmd.replaceAll("'", "'\\''")}'`;
// With extra commands, each one runs in its own shell so its operators cannot skip or mask the eng checks.
function preCommitBody(extra) {
  if (!extra.length) return ENG_CHECKS;
  return [`${ENG_CHECKS} || exit $?`, ...extra.map(cmd => `sh -c ${shQuote(cmd)} || exit $?`)].join('\n');
}
export function hooks(cfg) {
  const main = cfg.project.default_branch;
  const prot = [...new Set([main, ...(cfg.project.protected_branches ?? [])])];
  return {
    '.githooks/pre-rebase': `#!/bin/sh
${HDR()}
# Rebase is allowed on feature branches (pstack: small ordered commits, stacks rebase onto their parent).
# Verdicts bind to patch-id, so a rebase that keeps the patch keeps its verdict. Protected branches are never rebased.
b=\${2:-$(git rev-parse --abbrev-ref HEAD)}
for p in ${prot.join(' ')}; do [ "$b" = "$p" ] && { echo "eng: rebasing protected branch $b is blocked" >&2; exit 1; }; done
exit 0
`,
    '.githooks/pre-push': `#!/bin/sh
${HDR()}
# Blocks force-push (non-fast-forward) and deletion on protected branches: ${prot.join(', ')}.
# Feature branches may be force-pushed after a rebase (prefer --force-with-lease). A server ruleset is the real wall.
z=0000000000000000000000000000000000000000
while read lref lsha rref rsha; do
  for p in ${prot.join(' ')}; do
    [ "$rref" = "refs/heads/$p" ] || continue
    [ "$lsha" = "$z" ] && { echo "eng: deleting protected branch $p is blocked" >&2; exit 1; }
    if [ "$rsha" != "$z" ] && ! git merge-base --is-ancestor "$rsha" "$lsha" 2>/dev/null; then
      echo "eng: force-push to protected branch $p blocked" >&2; exit 1
    fi
  done
done
exit 0
`,
    '.githooks/pre-commit': `#!/bin/sh
${HDR()}
ENG="\${ENG:-npx --no-install eng}"  # set ENG (e.g. "bunx eng" or "node path/to/eng.mjs") where npx cannot run (bun repos with npm-incompatible overrides)
${preCommitBody(cfg.hooks?.pre_commit ?? [])}
`,
  };
}

export function claudeSettings(cfg) {
  const prot = [...new Set([cfg.project.default_branch, ...(cfg.project.protected_branches ?? [])])];
  const force = prot.flatMap(b => [`git push --force origin ${b}`, `git push -f origin ${b}`, `git push --force-with-lease origin ${b}`, `git push origin +${b}`, `git push origin --delete ${b}`]);
  const deny = [...force, 'git commit --no-verify', 'git commit -n', 'git push --no-verify', 'git merge --no-verify', 'gh pr merge --admin'];
  const postEdit = cfg.agents?.post_edit_command;
  const hooks = postEdit ? { hooks: { PostToolUse: [{ matcher: 'Edit|MultiEdit|Write', hooks: [{ type: 'command', command: postEdit, timeout: 60 }] }] } } : {};
  return JSON.stringify({ permissions: { deny: deny.map(d => `Bash(${d}:*)`) }, ...hooks }, null, 2) + '\n';
}

export function prTemplate() {
  return `<!-- ${HDR('').trim()} -->
## What and why

## Evidence
<!-- eng verify create output (fail on base, pass on HEAD) and the SHA it is bound to -->

## E2E / taste evidence
<!-- TesterArmy run link, video, screenshots -->

## Merge Danger
- Door: one-way / two-way
- Blast radius:

## Rollback
<!-- flag off first; DB is forward-fix only -->

## TesterArmy testing instructions
`;
}

// A vendored source keeps upstream layout: <src>/<name>, <src>/skills/<name>, or <src>/automations/*/skills/<name>.
function skillDir(src, name) {
  if (src === 'eng') { const d = path.join(PKG, 'skills', name); return fs.existsSync(d) ? d : null; }
  const base = path.join(PKG, 'vendor', src);
  const autos = fs.existsSync(path.join(base, 'automations')) ? fs.readdirSync(path.join(base, 'automations')).map(a => path.join(base, 'automations', a, 'skills', name)) : [];
  return [path.join(base, name), path.join(base, 'skills', name), ...autos].find(d => fs.existsSync(path.join(d, 'SKILL.md'))) ?? null;
}
// `<src>/*` installs every skill the source ships (pstack: skills/ and automations/*/skills/).
export function expandSkills(cfg) {
  return cfg.agents.skills.flatMap(s => {
    const [src, name] = s.split('/');
    if (name !== '*') return [s];
    const base = path.join(PKG, 'vendor', src), dirs = [path.join(base, 'skills')];
    if (fs.existsSync(path.join(base, 'automations'))) for (const a of fs.readdirSync(path.join(base, 'automations'))) dirs.push(path.join(base, 'automations', a, 'skills'));
    return dirs.filter(d => fs.existsSync(d)).flatMap(d => fs.readdirSync(d).filter(n => fs.existsSync(path.join(d, n, 'SKILL.md')))).sort().map(n => `${src}/${n}`);
  });
}

// skills: vendored (pinned upstream, path-rewritten) + ours
export function skills(cfg) {
  const out = {};
  let rewrite = t => t;
  const add = (srcDir, name) => {
    const walk = (d, rel = '') => {
      for (const f of fs.readdirSync(d, { withFileTypes: true })) {
        const p = path.join(d, f.name), r = path.join(rel, f.name);
        if (f.isDirectory()) walk(p, r);
        else if (f.name !== 'LICENSE') out[`${cfg.agents.skills_dir}/${name}/${r}`] = rewrite(fs.readFileSync(p, 'utf8'));
      }
    };
    walk(srcDir);
  };
  for (const s of expandSkills(cfg)) {
    const [src, name] = s.split('/');
    const dir = skillDir(src, name);
    if (!dir) throw new Error(`unknown skill ${s}`);
    const rw = path.join(PKG, 'vendor', src, 'REWRITES.tsv');
    const pairs = src !== 'eng' && fs.existsSync(rw) ? fs.readFileSync(rw, 'utf8').split('\n').filter(l => l && !l.startsWith('#')).map(l => l.split('\t').map(x => x.replaceAll('{skills_dir}', cfg.agents.skills_dir))) : [];
    rewrite = t => pairs.reduce((a, [f, to]) => a.replaceAll(f, to), t);
    add(dir, name);
    // Codex ignores disable-model-invocation; its switch is agents/openai.yaml policy.allow_implicit_invocation (developers.openai.com/codex/skills).
    const md = fs.readFileSync(path.join(dir, 'SKILL.md'), 'utf8'), fm = md.startsWith('---') ? md.split('---')[1] : '';
    const oy = `${cfg.agents.skills_dir}/${name}/agents/openai.yaml`;
    if (cfg.agents.harnesses.includes('codex') && /^disable-model-invocation:\s*true\s*$/m.test(fm) && !out[oy]) out[oy] = 'policy:\n  allow_implicit_invocation: false\n';
  }
  // A whole-source install also brings its subagent definitions (pstack: poteto-agent, Comment Sicko).
  for (const src of cfg.agents.skills.filter(s => s.endsWith('/*')).map(s => s.split('/')[0])) {
    const ad = path.join(PKG, 'vendor', src, 'agents');
    if (fs.existsSync(ad)) for (const f of fs.readdirSync(ad)) out[`${path.dirname(cfg.agents.skills_dir)}/agents/${f}`] = fs.readFileSync(path.join(ad, f), 'utf8');
  }
  return out;
}

// Vitest globalSetup (and any test/e2e runner hook): every test write goes under one per-run dir, removed at teardown.
export function testTmp(cfg) {
  const pre = `eng-${String(cfg.project.name).toLowerCase().replace(/[^a-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '') || 'repo'}-`;
  return `${HDR('//')}
// Per-run temp dir for tests. Wire it once in vitest.config.* (and vitest.*.config.*):
//   test: { globalSetup: ['./.eng/test-tmp.mjs'] }
// Under \`eng gate\` / \`eng e2e\`, ENG_TMP and TMPDIR already point at a dir eng removes on exit (also on failure or signal);
// run directly (\`vp test\`), this creates one and removes it at teardown. Tests write only under process.env.ENG_TMP:
//   fs.mkdtempSync(path.join(process.env.ENG_TMP, 'x-'))   // never bare os.tmpdir() (eng lint rule test-bare-tmpdir)
// A run killed with SIGKILL leaves its dir behind: \`eng clean --apply\` removes ${pre}* dirs older than ${cfg.hygiene?.tmp_max_age_hours ?? 6}h.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

export default function setup() {
  if (process.env.ENG_TMP && fs.existsSync(process.env.ENG_TMP)) return;
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), \`${pre}\${Date.now().toString(36)}-\${process.pid}-\`));
  process.env.ENG_TMP = dir; process.env.TMPDIR = dir;
  const rm = () => fs.rmSync(dir, { recursive: true, force: true });
  process.once('exit', rm);
  return rm;
}
`;
}

export function renderAll(cfg, existingAgents) {
  const files = {
    'STACK.md': stackMd(cfg),
    'SHIPPING.md': shippingMd(cfg),
    'CLAUDE.md': '@AGENTS.md\n',
    '.github/pull_request_template.md': prTemplate(),
    '.eng/ci/pipeline.yml': pipeline(cfg),
    ...(cfg.audits?.maintain_verification ? { '.eng/ci/audit.yml': auditPipeline(cfg) } : {}),
    ...(cfg.e2e && resolvePolicy(cfg.e2e).main.nightly.enabled ? { '.eng/ci/e2e-nightly.yml': e2eNightlyPipeline(cfg) } : {}),
    '.eng/test-tmp.mjs': testTmp(cfg),
    ...hooks(cfg),
    ...skills(cfg),
  };
  if (cfg.agents.harnesses.includes('claude-code')) files['.claude/settings.json'] = claudeSettings(cfg);
  // AGENTS.md: only the block is ours; text outside belongs to people.
  const block = agentsBlock(cfg);
  let a = existingAgents ?? `# AGENTS.md\n\n${block}\n`;
  if (a.includes(BEGIN) && a.includes(END)) a = a.slice(0, a.indexOf(BEGIN)) + block + a.slice(a.indexOf(END) + END.length);
  else a = a.trimEnd() + '\n\n' + block + '\n';
  files['AGENTS.md'] = a;
  return files;
}
